import React from "react";

export default function EventData() {
    const n1 = 20;
    const n2 = 4;

    // ฟังก์ชันสำหรับสลับปุ่ม Start / Stop
    const onClickStartStop = (ev) => {
        let t = ev.target.innerText;
        let s = (t === 'Start' || t === 'start') ? 'Stop' : 'Start';
        ev.target.innerText = s;
        alert(`You clicked ${t}`);
    };

    // ฟังก์ชันคำนวณตัวเลข
    const handleCalculate = (op) => {
        let result = eval(op);
        alert(`${op} = ${result}`);
    };

    return (
        <div style={{ textAlign: 'center', marginTop: 20 }}>
            {/* เปลี่ยนเป็น onClick (C ตัวใหญ่) และเรียกใช้ onClickStartStop */}
            <button onClick={(ev) => onClickStartStop(ev)}>Start</button><br/><br/>
            
            <button onClick={() => handleCalculate(`${n1} + ${n2}`)}>10 + 20</button><br/><br/>
            
            <button onClick={() => handleCalculate('30 * 40')}>30 * 40</button><br/><br/>
        </div>
    );
}
